    {
      partId: "part2", partTitle: "பகுதி - II / PART - II (2 மதிப்பெண் வினாக்கள்)",
      instruction: "குறிப்பு: எவையேனும் 10 வினாக்களுக்கு விடையளிக்கவும். வினா எண் 28-க்கு கட்டாயமாக விடையளிக்க வேண்டும்.",
      totalMarks: 20, markEach: 2,
      questions: [
        { id: "pub_m_tm_22_q15", qNum: 15, type: "2m", mark: "2 மதிப்பெண்", topic: "உறவுகள்", q: "A = {1, 2, 3} மற்றும் B = {4, 5, 6} எனில் A × B-ஐக் காண்க.", ans: "<b>தீர்வு:</b><br>A × B = {(1, 4), (1, 5), (1, 6), (2, 4), (2, 5), (2, 6), (3, 4), (3, 5), (3, 6)}.", markingScheme: "A × B எழுதுதல்: 2 மதிப்பெண்கள்", isCompulsory: false },
        { id: "pub_m_tm_22_q16", qNum: 16, type: "2m", mark: "2 மதிப்பெண்", topic: "எண்களும் தொடர்வரிசைகளும்", q: "3, 15, 27, 39, ... என்ற தொடர்வரிசையின் அடுத்த மூன்று உறுப்புகளைக் காண்க.", ans: "<b>தீர்வு:</b><br>பொது வித்தியாசம் d = 15 - 3 = 12.<br>அடுத்த உறுப்புகள்: 39 + 12 = <b>51</b>; 51 + 12 = <b>63</b>; 63 + 12 = <b>75</b>.", markingScheme: "d = 12: 1M, அடுத்த 3 உறுப்புகள்: 1M = 2 மதிப்பெண்கள்", isCompulsory: false },
        { id: "pub_m_tm_22_q17", qNum: 17, type: "2m", mark: "2 மதிப்பெண்", topic: "இருபடிச் சமன்பாடு", q: "சூத்திர முறையைப் பயன்படுத்தித் தீர்க்க: x² + 2x - 2 = 0", ans: "<b>தீர்வு:</b><br>a = 1, b = 2, c = -2.<br>x = [-b ± √(b² - 4ac)] / 2a = [-2 ± √(4 - 4(1)(-2))] / 2 = [-2 ± √12] / 2 = [-2 ± 2√3] / 2 = <b>-1 ± √3</b>.", markingScheme: "சூத்திரம்: 1M, தீர்வு -1 ± √3: 1M = 2 மதிப்பெண்கள்", isCompulsory: false },
        { id: "pub_m_tm_22_q18", qNum: 18, type: "2m", mark: "2 மதிப்பெண்", topic: "இயற்கணிதம்", q: "இரு எண்களின் கூடுதல் 27 மற்றும் பெருக்கற்பலன் 182 எனில் அவ்விரு எண்களைக் காண்க.", ans: "<b>தீர்வு:</b><br>x(27 - x) = 182 ⇒ x² - 27x + 182 = 0 ⇒ (x - 13)(x - 14) = 0.<br>அவ்விரு எண்கள் <b>13 மற்றும் 14</b> ஆகும்.", markingScheme: "சமன்பாடு: 1M, எண்கள் 13, 14: 1M = 2 மதிப்பெண்கள்", isCompulsory: false },
        { id: "pub_m_tm_22_q19", qNum: 19, type: "2m", mark: "2 மதிப்பெண்", topic: "வடிவியல்", q: "வடிவொத்த முக்கோணங்கள் என்றால் என்ன?", ans: "<b>வரையறை:</b> இரு முக்கோணங்களின் ஒத்த கோணங்கள் சமமாகவும், ஒத்த பக்கங்கள் சம விகிதத்திலும் அமைந்தால் அவை வடிவொத்த முக்கோணங்கள் (Similar Triangles) எனப்படும்.", markingScheme: "சரியான வரையறை: 2 மதிப்பெண்கள்", isCompulsory: false },
        { id: "pub_m_tm_22_q20", qNum: 20, type: "2m", mark: "2 மதிப்பெண்", topic: "ஆயத்தொலை வடிவியல்", q: "(1, -1) மற்றும் (-4, 6) ஆகிய புள்ளிகள் வழிச் செல்லும் நேர்கோட்டின் சாய்வைக் காண்க.", ans: "<b>தீர்வு:</b><br>m = (y₂ - y₁) / (x₂ - x₁) = [6 - (-1)] / (-4 - 1) = 7 / -5 = <b>-7/5</b>.", markingScheme: "சூத்திரம்: 1M, விடை: 1M = 2 மதிப்பெண்கள்", isCompulsory: false },
        { id: "pub_m_tm_22_q21", qNum: 21, type: "2m", mark: "2 மதிப்பெண்", topic: "நேர்கோடுகள்", q: "2x + 3y - 6 = 0 என்ற கோட்டின் வெட்டுத்துண்டுகளைக் காண்க.", ans: "<b>தீர்வு:</b><br>2x + 3y = 6 ⇒ (x/3) + (y/2) = 1.<br><b>X-வெட்டுத்துண்டு a = 3, Y-வெட்டுத்துண்டு b = 2</b>.", markingScheme: "வெட்டுத்துண்டு வடிவம்: 1M, a = 3, b = 2: 1M = 2 மதிப்பெண்கள்", isCompulsory: false },
        { id: "pub_m_tm_22_q22", qNum: 22, type: "2m", mark: "2 மதிப்பெண்", topic: "முக்கோணவியல்", q: "நிரூபிக்க: tan θ + cot θ = sec θ cosec θ", ans: "<b>தீர்வு:</b><br>LHS = (sin θ / cos θ) + (cos θ / sin θ) = (sin²θ + cos²θ) / (sin θ cos θ) = 1 / (sin θ cos θ) = <b>sec θ cosec θ = RHS</b>.", markingScheme: "LHS மாற்றம்: 1M, நிறுவுதல்: 1M = 2 மதிப்பெண்கள்", isCompulsory: false },
        { id: "pub_m_tm_22_q23", qNum: 23, type: "2m", mark: "2 மதிப்பெண்", topic: "உயரங்களும் தொலைவுகளும்", q: "ஒரு சுவரின் மீது சார்த்தி வைக்கப்பட்டுள்ள 15 மீ நீளமுள்ள ஏணி தரைமட்டத்துடன் 60° கோணத்தை ஏற்படுத்துகிறது எனில், சுவர் ஏணியை தொடும் உயரம் காண்க.", ans: "<b>தீர்வு:</b><br>sin 60° = h / 15 ⇒ √3 / 2 = h / 15 ⇒ h = 15√3 / 2 = <b>7.5√3 மீ (அல்லது 12.99 மீ)</b>.", markingScheme: "சூத்திரம்: 1M, உயரம்: 1M = 2 மதிப்பெண்கள்", isCompulsory: false },
        { id: "pub_m_tm_22_q24", qNum: 24, type: "2m", mark: "2 மதிப்பெண்", topic: "அளவியல்", q: "ஒரு கோளத்தின் ஆரம் 10.5 செ.மீ எனில் அதன் புறப்பரப்பைக் காண்க.", ans: "<b>தீர்வு:</b><br>புறப்பரப்பு = 4πr² = 4 × (22 / 7) × 10.5 × 10.5 = 4 × 22 × 1.5 × 10.5 = <b>1386 செ.மீ²</b>.", markingScheme: "சூத்திரம்: 1M, விடை: 1M = 2 மதிப்பெண்கள்", isCompulsory: false },
        { id: "pub_m_tm_22_q25", qNum: 25, type: "2m", mark: "2 மதிப்பெண்", topic: "உள்ளீடற்ற உருளை", q: "உள்ளீடற்ற உருளையின் கனஅளவுக்கான சூத்திரத்தை எழுதி விளக்குக.", ans: "<b>தீர்வு:</b><br>கனஅளவு V = π (R² - r²) h க.அலகுகள்.<br>இங்கு R = வெளி ஆரம், r = உள் ஆரம், h = உயரம்.", markingScheme: "சூத்திரம்: 1M, விளக்கக் குறிப்பு: 1M = 2 மதிப்பெண்கள்", isCompulsory: false },
        { id: "pub_m_tm_22_q26", qNum: 26, type: "2m", mark: "2 மதிப்பெண்", topic: "புள்ளியியல்", q: "முதல் 21 இயல் எண்களின் திட்டவிலக்கத்தைக் காண்க.", ans: "<b>தீர்வு:</b><br>சூத்திரம் σ = √[(n² - 1) / 12]<br>σ = √[(21² - 1) / 12] = √[(441 - 1) / 12] = √(440 / 12) = √36.67 ≈ <b>6.05</b>.", markingScheme: "சூத்திரம்: 1M, விடை 6.05: 1M = 2 மதிப்பெண்கள்", isCompulsory: false },
        { id: "pub_m_tm_22_q27", qNum: 27, type: "2m", mark: "2 மதிப்பெண்", topic: "நிகழ்தகவு", q: "ஒரு சீரான பகடை உருட்டப்படும் போது, 4-ஐ விடப் பெரிய எண் கிடைப்பதற்கான நிகழ்தகவு யாது?", ans: "<b>தீர்வு:</b><br>n(S) = 6. சாதகமான விளைவுகள் E = {5, 6} ⇒ n(E) = 2.<br>P(E) = 2 / 6 = <b>1 / 3</b>.", markingScheme: "கூறுவெளி: 1M, விடை 1/3: 1M = 2 மதிப்பெண்கள்", isCompulsory: false },
        { id: "pub_m_tm_22_q28", qNum: 28, type: "2m", mark: "2 மதிப்பெண்", topic: "நேர்கோடுகள் (கட்டாய வினா)", q: "A(5, 1) மற்றும் B(3, 4) ஆகிய புள்ளிகளை இணைக்கும் கோட்டுத்துண்டிற்குச் செங்குத்தான கோட்டின் சாய்வைக் காண்க.", ans: "<b>தீர்வு (வினா எண் 28 - கட்டாய வினா):</b><br>AB-ன் சாய்வு m₁ = (y₂ - y₁) / (x₂ - x₁) = (4 - 1) / (3 - 5) = 3 / (-2) = -3/2.<br>செங்குத்துக் கோட்டின் சாய்வு m₂ எனில்:<br>m₁ × m₂ = -1<br>(-3/2) × m₂ = -1<br><b>m₂ = 2/3</b>.<br><b>விடை: செங்குத்துக் கோட்டின் சாய்வு = 2/3</b>.", markingScheme: "AB-ன் சாய்வு m₁ = -3/2: 1M, செங்குத்துச் சாய்வு m₂ = 2/3: 1M = 2 மதிப்பெண்கள்", isCompulsory: true }
      ]
    },
    {
      partId: "part3", partTitle: "பகுதி - III / PART - III (5 மதிப்பெண் வினாக்கள்)",
      instruction: "குறிப்பு: எவையேனும் 10 வினாக்களுக்கு விடையளிக்கவும். வினா எண் 42-க்கு கட்டாயமாக விடையளிக்க வேண்டும்.",
      totalMarks: 50, markEach: 5,
      questions: [
        { id: "pub_m_tm_22_q29", qNum: 29, type: "5m", mark: "5 மதிப்பெண்", topic: "டி மார்கனின் விதி", q: "A = {b, c, e, g, h}, B = {a, c, d, g, i} மற்றும் C = {a, d, e, g, h} எனில், A - (B ∩ C) = (A - B) ∪ (A - C) என நிறுவுக.", ans: "<b>தீர்வு:</b><br>B ∩ C = {a, d, g}.<br>LHS = A - (B ∩ C) = {b, c, e, h} ---- (1)<br>A - B = {b, e, h}, A - C = {b, c}.<br>RHS = (A - B) ∪ (A - C) = {b, c, e, h} ---- (2)<br>(1) = (2) என்பதால் நிறுவப்பட்டது.", markingScheme: "B∩C மற்றும் LHS: 2½M, RHS: 2½M = 5 மதிப்பெண்கள்", isCompulsory: false },
        { id: "pub_m_tm_22_q30", qNum: 30, type: "5m", mark: "5 மதிப்பெண்", topic: "விகிதமுறு கோவைகளின் கூட்டல்", q: "சுருக்குக: 1 / (x² - 5x + 6) + 1 / (x² - 3x + 2) - 1 / (x² - 8x + 15)", ans: "<b>தீர்வு:</b><br>பகுதிகளைக் காரணிப்படுத்த:<br>= 1/[(x-2)(x-3)] + 1/[(x-1)(x-2)] - 1/[(x-3)(x-5)]<br>பொது மீ.பொ.ம எடுத்து சுருக்க எளிமையான விடை பெறப்படுகிறது.", markingScheme: "காரணிப்படுத்துதல்: 2M, மீ.பொ.ம எடுத்து கூட்டல்: 2M, விடை: 1M = 5 மதிப்பெண்கள்", isCompulsory: false },
        { id: "pub_m_tm_22_q31", qNum: 31, type: "5m", mark: "5 மதிப்பெண்", topic: "வர்க்கமூலம் காணுதல்", q: "நீள்வகுத்தல் முறையில் வர்க்கமூலம் காண்க: 16x⁴ + 8x³ + 17x² + 4x + 4", ans: "<b>தீர்வு:</b><br>நீள்வகுத்தல் முறைப்படி தீர்வு காண: ஈவு 4x² + x + 2 கிடைக்கிறது.<br><b>விடை: |4x² + x + 2|</b>.", markingScheme: "படிநிலைகள்: 3M, ஈவு: 1M, விடை: 1M = 5 மதிப்பெண்கள்", isCompulsory: false },
        { id: "pub_m_tm_22_q32", qNum: 32, type: "5m", mark: "5 மதிப்பெண்", topic: "கூட்டுத்தொடர்வரிசை", q: "ஒரு கூட்டுத்தொடர்வரிசையின் 9-வது உறுப்பின் 9 மடங்கும், 15-வது உறுப்பின் 15 மடங்கும் சமம் எனில், 24-வது உறுப்பின் 6 மடங்கு பூச்சியம் என நிறுவுக.", ans: "<b>தீர்வு:</b><br>9 t₉ = 15 t₁₅ ⇒ 9(a + 8d) = 15(a + 14d) ⇒ 9a + 72d = 15a + 210d ⇒ 6a + 138d = 0 ⇒ 6(a + 23d) = 0.<br>t₂₄ = a + 23d என்பதால்: <b>6 t₂₄ = 0</b>. நிறுவப்பட்டது.", markingScheme: "சமன்பாடு அமைத்தல்: 2M, சுருக்குதல்: 2M, நிறுவுதல்: 1M = 5 மதிப்பெண்கள்", isCompulsory: false },
        { id: "pub_m_tm_22_q33", qNum: 33, type: "5m", mark: "5 மதிப்பெண்", topic: "பித்தாகரஸ் தேற்றம் பயன்பாடு", q: "ஒரு செங்கோண முக்கோணத்தின் பக்கங்கள் x - 1, x மற்றும் x + 1 எனில் அதன் பக்கங்களின் நீளங்களைக் காண்க.", ans: "<b>தீர்வு:</b><br>(x + 1)² = x² + (x - 1)² ⇒ x² + 2x + 1 = x² + x² - 2x + 1 ⇒ x² - 4x = 0 ⇒ x(x - 4) = 0.<br>பக்க நீளம் மிகை எண் என்பதால் x = 4.<br>பக்கங்கள்: x - 1 = 3 செ.மீ, x = 4 செ.மீ, x + 1 = <b>5 செ.மீ</b>.", markingScheme: "பித்தாகரஸ் சமன்பாடு: 2M, x = 4 காணுதல்: 2M, பக்கங்கள் 3, 4, 5: 1M = 5 மதிப்பெண்கள்", isCompulsory: false },
        { id: "pub_m_tm_22_q34", qNum: 34, type: "5m", mark: "5 மதிப்பெண்", topic: "நாற்கரத்தின் பரப்பு", q: "(-4, -2), (-3, -5), (3, -2) மற்றும் (2, 3) என்ற புள்ளிகளை முனைகளாகக் கொண்ட நாற்கரத்தின் பரப்பைக் காண்க.", ans: "<b>தீர்வு:</b><br>வரிசைப்படுத்தப்பட்ட புள்ளிகளுக்கு சூத்திரம் பிரதியிட: பரப்பு = <b>28 ச.அலகுகள்</b> கிடைக்கிறது.", markingScheme: "சூத்திரம்: 1M, பிரதியிடுதல்: 2M, விடை 28 ச.அலகுகள்: 2M = 5 மதிப்பெண்கள்", isCompulsory: false },
        { id: "pub_m_tm_22_q35", qNum: 35, type: "5m", mark: "5 மதிப்பெண்", topic: "நேர்கோடுகள்", q: "A(-5, 7), B(-4, -5), C(-1, -6) மற்றும் D(4, 5) உச்சிப் புள்ளிகளைக் கொண்ட நாற்கரத்தின் பக்கங்களின் நடுப்புள்ளிகள் ஓர் இணைகரத்தை அமைக்கும் எனக் காட்டுக.", ans: "<b>தீர்வு:</b><br>நடுப்புள்ளிகள் P, Q, R, S காணுதல். எதிரெதிர் பக்கங்களின் சாய்வுகள் சமம் எனக் காட்டி இணைகரம் என நிறுவுதல்.", markingScheme: "நடுப்புள்ளிகள்: 2M, சாய்வுகள் சமம் எனக் காட்டுதல்: 2M, முடிவு: 1M = 5 மதிப்பெண்கள்", isCompulsory: false },
        { id: "pub_m_tm_22_q36", qNum: 36, type: "5m", mark: "5 மதிப்பெண்", topic: "முக்கோணவியல் பயன்பாடு", q: "ஒரு பல அடுக்குக் கட்டிடத்தின் உச்சியிலிருந்து 8 மீ உயரமுள்ள கட்டிடத்தின் உச்சி மற்றும் அடியின் இறக்கக் கோணங்கள் முறையே 30° மற்றும் 45° எனில், பல அடுக்குக் கட்டிடத்தின் உயரம் மற்றும் அவற்றுக்கு இடையே உள்ள தொலைவைக் காண்க.", ans: "<b>தீர்வு:</b><br>உயரம் h = 4(3 + √3) மீ மற்றும் தொலைவு d = 4(3 + √3) மீ = <b>18.93 மீ</b>.", markingScheme: "படம்: 1M, சமன்பாடுகள்: 2M, தீர்வு 18.93 மீ: 2M = 5 மதிப்பெண்கள்", isCompulsory: false },
        { id: "pub_m_tm_22_q37", qNum: 37, type: "5m", mark: "5 மதிப்பெண்", topic: "அளவியல்", q: "ஒரு நேர்வட்டக் கூம்பின் கனஅளவு 11088 க.செ.மீ மற்றும் அதன் உயரம் 24 செ.மீ எனில் அதன் ஆரத்தைக் காண்க.", ans: "<b>தீர்வு:</b><br>⅓ π r² h = 11088 ⇒ ⅓ × (22 / 7) × r² × 24 = 11088 ⇒ r² = 441 ⇒ <b>r = 21 செ.மீ</b>.", markingScheme: "சூத்திரம்: 1M, சுருக்குதல்: 2M, ஆரம் r = 21 செ.மீ: 2M = 5 மதிப்பெண்கள்", isCompulsory: false },
        { id: "pub_m_tm_22_q38", qNum: 38, type: "5m", mark: "5 மதிப்பெண்", topic: "திட்டவிலக்கம்", q: "ஒரு வகுப்பிலுள்ள மாணவர்கள் பெற்ற மதிப்பெண்கள்: 15, 10, 20, 25, 30. இத்தரவுகளுக்கு திட்டவிலக்கம் காண்க.", ans: "<b>தீர்வு:</b><br>சராசரி x̄ = 100 / 5 = 20.<br>விலக்க வர்க்கங்களின் கூடுதல் Σd² = 25 + 100 + 0 + 25 + 100 = 250.<br>திட்டவிலக்கம் σ = √(250 / 5) = √50 ≈ <b>7.07</b>.", markingScheme: "சராசரி 20: 1M, விலக்கங்கள்: 2M, திட்டவிலக்கம் 7.07: 2M = 5 மதிப்பெண்கள்", isCompulsory: false },
        { id: "pub_m_tm_22_q39", qNum: 39, type: "5m", mark: "5 மதிப்பெண்", topic: "நிகழ்தகவு", q: "ஒரு சீரான நாணயம் 3 முறை சுண்டப்படுகிறது. (i) சரியாக இரண்டு தலைகள் (ii) குறைந்தது ஒரு தலை (iii) அதிகபட்சமாக இரண்டு பூக்கள் கிடைக்க நிகழ்தகவு காண்க.", ans: "<b>தீர்வு:</b><br>n(S) = 8.<br>(i) சரியாக இரு தலைகள்: 3/8.<br>(ii) குறைந்தது ஒரு தலை: 7/8.<br>(iii) அதிகபட்சமாக இரு பூக்கள்: 7/8.", markingScheme: "கூறுவெளி: 1M, (i) 3/8: 1M, (ii) 7/8: 1½M, (iii) 7/8: 1½M = 5 மதிப்பெண்கள்", isCompulsory: false },
        { id: "pub_m_tm_22_q40", qNum: 40, type: "5m", mark: "5 மதிப்பெண்", topic: "சிறப்புத் தொடர்கள்", q: "1² + 2² + 3² + ... + 19² -ன் கூடுதல் காண்க.", ans: "<b>தீர்வு:</b><br>சூத்திரம் Σn² = n(n + 1)(2n + 1) / 6.<br>n = 19 ⇒ 19 × 20 × 39 / 6 = 19 × 10 × 13 = <b>2470</b>.", markingScheme: "சூத்திரம்: 1M, பிரதியிடுதல்: 2M, விடை 2470: 2M = 5 மதிப்பெண்கள்", isCompulsory: false },
        { id: "pub_m_tm_22_q41", qNum: 41, type: "5m", mark: "5 மதிப்பெண்", topic: "அளவியல்", q: "ஒரு திண்ம இரும்புக் கோளத்தின் ஆரம் 8 செ.மீ. இதனை உருக்கி 1 செ.மீ ஆரமுள்ள எத்தனை சிறிய திண்மக் கோளங்களாக மாற்றலாம்?", ans: "<b>தீர்வு:</b><br>பெரிய கோளத்தின் கனஅளவு = 4/3 π (8)³ = 4/3 π (512).<br>சிறிய கோளத்தின் கனஅளவு = 4/3 π (1)³ = 4/3 π (1).<br>சிறிய கோளங்களின் எண்ணிக்கை = 512 / 1 = <b>512 கோளங்கள்</b>.", markingScheme: "கனஅளவு சூத்திரங்கள்: 2M, வகுத்தல்: 1M, விடை 512: 2M = 5 மதிப்பெண்கள்", isCompulsory: false },
        { id: "pub_m_tm_22_q42", qNum: 42, type: "5m", mark: "5 மதிப்பெண்", topic: "அளவியல் (கட்டாய வினா)", q: "ஓர் இடைக்கண்ட வடிவிலான வாளியின் மேற்புற மற்றும் அடிப்புற ஆரங்கள் முறையே 28 செ.மீ மற்றும் 7 செ.மீ, அதன் ஆழம் 45 செ.மீ எனில், வாளியின் கொள்ளளவை லிட்டரில் காண்க.", ans: "<b>தீர்வு (வினா எண் 42 - கட்டாய வினா):</b><br>R = 28 செ.மீ, r = 7 செ.மீ, h = 45 செ.மீ.<br>வாளியின் கொள்ளளவு (கனஅளவு) V = ⅓ π h (R² + Rr + r²)<br>= ⅓ × (22 / 7) × 45 × (28² + 28(7) + 7²)<br>= 15 × (22 / 7) × (784 + 196 + 49)<br>= (330 / 7) × 1029 = 330 × 147 = <b>48510 க.செ.மீ</b>.<br><br><b>லிட்டருக்கு மாற்றுதல்:</b><br>1000 க.செ.மீ = 1 லிட்டர்.<br>கொள்ளளவு = 48510 / 1000 = <b>48.51 லிட்டர்</b>.<br><br><b>விடை: வாளியின் கொள்ளளவு = 48.51 லிட்டர்</b>.", markingScheme: "சூத்திரம்: 1M, கணக்கீடு (48510 க.செ.மீ): 2M, லிட்டரில் மாற்றி விடை தருதல் (48.51 லி): 2M = 5 மதிப்பெண்கள்", isCompulsory: true }
      ]
    },
    {
      partId: "part4", partTitle: "பகுதி - IV / PART - IV (8 மதிப்பெண் வினாக்கள்)",
      instruction: "குறிப்பு: அனைத்து வினாக்களுக்கும் விடையளிக்கவும். ஒவ்வொரு வினாவிலும் கொடுக்கப்பட்டுள்ள அல்லது வினாவைத் தேர்ந்தெடுத்து விடையளிக்கவும்.",
      totalMarks: 16, markEach: 8,
      questions: [
        { id: "pub_m_tm_22_q43", qNum: 43, type: "8m", mark: "8 மதிப்பெண்", topic: "வடிவியல்", q: "(அ) AB = 5.5 செ.மீ, ∠C = 40° மற்றும் உச்சி C-யிலிருந்து AB-க்கு வரையப்பட்ட நடுக்கோட்டின் நீளம் 4.5 செ.மீ கொண்ட ΔABC வரைக.<br><br><b>(அல்லது)</b><br><br>(ஆ) 6 செ.மீ விட்டமுள்ள வட்டம் வரைந்து வட்டத்தின் மையத்திலிருந்து 8 செ.மீ தொலைவில் ஒரு புள்ளியைக் குறித்து அப்புள்ளியிலிருந்து வட்டத்திற்குத் தொடுகோடுகள் வரைக.", ans: "<b>தீர்வு:</b><br>(அ) நடுக்கோடு கொண்ட முக்கோணம் வரைதல்.<br>(ஆ) தொடுகோடுகள் வரைதல்: ஆரம் = 3 செ.மீ, d = 8 செ.மீ. தொடுகோட்டின் நீளம் = √(8² - 3²) = √55 ≈ <b>7.4 செ.மீ</b>.", markingScheme: "உதவிப்படம்: 1M, உண்மைப்படம்: 4M, வரைமுறை: 2M, அளவீடு: 1M = 8 மதிப்பெண்கள்", isCompulsory: false },
        { id: "pub_m_tm_22_q44", qNum: 44, type: "8m", mark: "8 மதிப்பெண்", topic: "வரைபடம்", q: "(அ) y = x² - 8x + 16 என்ற இருபடிச் சமன்பாட்டின் வரைபடம் வரைந்து மூலங்களின் தன்மையைக் காண்க.<br><br><b>(அல்லது)</b><br><br>(ஆ) y = x² - 5x + 6 வரைபடம் வரைந்து x² - 5x + 6 = 0 என்ற சமன்பாட்டைத் தீர்க்க.", ans: "<b>தீர்வு:</b><br>(அ) y = x² - 8x + 16-ன் வரைபடம் X-அச்சை (4, 0) என்ற ஒரே புள்ளியில் தொட்டுச் செல்கிறது. எனவே சமன்பாட்டின் மூலங்கள் <b>மெய் மற்றும் சமம் {4, 4}</b>.", markingScheme: "அட்டவணை: 2M, வரைபடம்: 4M, தீர்வு: 2M = 8 மதிப்பெண்கள்", isCompulsory: false }
      ]
    }
