            { id: "pub_eng_24_q14", qNum: 14, type: "1m", mark: "1 Mark", topic: "Linkers", q: "He worked hard ________ he failed.", options: ["(a) but", "(b) and", "(c) so", "(d) because"], correctOption: "(a) but", ans: "<b>Answer: (a) but</b>", isCompulsory: false }
