          instruction: "Answer any 10 questions. Section 1 (Prose): Any 3. Section 2 (Poetry): Any 3. Section 3 (Grammar): Any 3. Section 4: Question No. 28 is Compulsory.",
          totalMarks: 20, markEach: 2,
          questions: [
            { id: "pub_eng_24_q15", qNum: 15, type: "2m", mark: "2 Marks", topic: "Prose - His First Flight", q: "Why did the seagull fail to fly?", ans: "The young seagull failed to fly because he was afraid that his wings would never support him over the vast green sea.", markingScheme: "Correct answer: 2 Marks", isCompulsory: false },
            { id: "pub_eng_24_q16", qNum: 16, type: "2m", mark: "2 Marks", topic: "Prose - The Night the Ghost Got In", q: "What caused the commotion in the narrator's house?", ans: "The narrator heard the sound of footsteps circling the dining-room table at 1:15 a.m., which he mistook for a ghost, creating panic in the house.", markingScheme: "Correct answer: 2 Marks", isCompulsory: false },
            { id: "pub_eng_24_q17", qNum: 17, type: "2m", mark: "2 Marks", topic: "Prose - Empowered Women Navigating the World", q: "What was INSV Tarini?", ans: "INSV Tarini was the second sailboat of the Indian Navy, built indigenously, used by the all-women crew for circumnavigating the globe.", markingScheme: "Correct answer: 2 Marks", isCompulsory: false },
            { id: "pub_eng_24_q18", qNum: 18, type: "2m", mark: "2 Marks", topic: "Prose - The Attic", q: "Where was Nagen uncle's tea shop located?", ans: "Nagen uncle's tea shop was located next to a grocery shop and opposite a temple dedicated to Lord Shiva in Bramhapur.", markingScheme: "Correct answer: 2 Marks", isCompulsory: false },
            { id: "pub_eng_24_q19", qNum: 19, type: "2m", mark: "2 Marks", topic: "Poetry - Life", q: "\"Let me but live my life from year to year,<br>With forward face and unreluctant soul;\"<br>(a) How does the poet want to live his life?<br>(b) What is meant by 'unreluctant soul'?", ans: "(a) The poet wants to live his life with courage, forward-looking attitude, and joy every year.<br>(b) 'Unreluctant soul' means a willing, eager, and open-hearted mind without hesitation.", markingScheme: "(a) 1M, (b) 1M = 2 Marks", isCompulsory: false },
            { id: "pub_eng_24_q20", qNum: 20, type: "2m", mark: "2 Marks", topic: "Poetry - I am Every Woman", q: "\"A woman is beauty innate,<br>A symbol of power and strength.\"<br>(a) How is a woman described?<br>(b) What does 'innate' mean?", ans: "(a) A woman is described as inborn beauty and an embodiment of power and strength.<br>(b) 'Innate' means inborn or natural.", markingScheme: "(a) 1M, (b) 1M = 2 Marks", isCompulsory: false },
            { id: "pub_eng_24_q21", qNum: 21, type: "2m", mark: "2 Marks", topic: "Poetry - The Ant and the Cricket", q: "\"A silly young cricket, accustomed to sing<br>Through the warm, sunny months of gay summer and spring,\"<br>(a) What was the cricket accustomed to do?<br>(b) What months are mentioned?", ans: "(a) The cricket was accustomed to singing and enjoying all day.<br>(b) The warm, sunny months of summer and spring.", markingScheme: "(a) 1M, (b) 1M = 2 Marks", isCompulsory: false },
            { id: "pub_eng_24_q22", qNum: 22, type: "2m", mark: "2 Marks", topic: "Poetry - The Secret of the Machines", q: "\"We can pull and haul and push and lift and drive,<br>We can print and plough and weave and heat and light,\"<br>Identify the figure of speech used here.", ans: "Figure of speech: <b>Personification</b> (The machines describe their abilities using the human pronoun 'We') and <b>Hyperbaton / Anaphora</b>.", markingScheme: "Correct figure of speech: 2 Marks", isCompulsory: false },
            { id: "pub_eng_24_q23", qNum: 23, type: "2m", mark: "2 Marks", topic: "Grammar - Active/Passive Voice", q: "Change into Passive voice:<br>The chef prepares a delicious meal.", ans: "<b>Passive Voice: A delicious meal is prepared by the chef.</b>", markingScheme: "Correct transformation: 2 Marks", isCompulsory: false },
            { id: "pub_eng_24_q24", qNum: 24, type: "2m", mark: "2 Marks", topic: "Grammar - Direct/Indirect Speech", q: "Change into Indirect speech:<br>Ravi said, \"I am going to Chennai tomorrow.\"", ans: "<b>Indirect Speech: Ravi said that he was going to Chennai the next day.</b>", markingScheme: "Correct transformation: 2 Marks", isCompulsory: false },
            { id: "pub_eng_24_q25", qNum: 25, type: "2m", mark: "2 Marks", topic: "Grammar - Punctuation", q: "Punctuate the following sentence:<br>where are you going asked my mother", ans: "<b>\"Where are you going?\" asked my mother.</b>", markingScheme: "Correct punctuation: 2 Marks", isCompulsory: false },
            { id: "pub_eng_24_q26", qNum: 26, type: "2m", mark: "2 Marks", topic: "Grammar - Simple/Compound", q: "Transform into a Complex sentence:<br>In spite of his illness, he attended the meeting.", ans: "<b>Complex Sentence: Though he was ill, he attended the meeting. (or Although he was ill...)</b>", markingScheme: "Correct transformation: 2 Marks", isCompulsory: false },
            { id: "pub_eng_24_q27", qNum: 27, type: "2m", mark: "2 Marks", topic: "Grammar - Rearrange Words", q: "Rearrange the words to form a meaningful sentence:<br>library / the / in / silence / maintain / please", ans: "<b>Please maintain silence in the library.</b>", markingScheme: "Correct sentence: 2 Marks", isCompulsory: false },
            { id: "pub_eng_24_q28", qNum: 28, type: "2m", mark: "2 Marks", topic: "Road Map Directions (Compulsory Question)", q: "A stranger wants to visit the Government Hospital. Guide him with clear step-by-step directions from the Bus Stand.", ans: "<b>Directions (Question No. 28 - Compulsory Question):</b><br>1. Step out of the Bus Stand and walk straight along Mahatma Gandhi Road.<br>2. At the roundana junction, turn left onto Anna Salai.<br>3. Walk past the State Bank of India on your right.<br>4. You will find the Government Hospital right opposite the Post Office.<br><b>(Walk straight ➔ Turn left at roundana ➔ Destination is on your left opposite Post Office)</b>.", markingScheme: "3 to 4 clear directional steps: 2 Marks", isCompulsory: true }
          ]
